#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumTotalPrice(int n, std::vector<std::vector<int>>& edges, std::vector<int>& price, std::vector<std::vector<int>>& trips) {
        std::vector<std::vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> count(n, 0);
        for (auto& t : trips) {
            int start = t[0], end = t[1];
            std::vector<int> path;
            auto findPath = [&](auto self, int u, int p) -> bool {
                path.push_back(u);
                if (u == end) return true;
                for (int v : adj[u]) {
                    if (v != p && self(self, v, u)) return true;
                }
                path.pop_back();
                return false;
            };
            findPath(findPath, start, -1);
            for (int u : path) count[u]++;
        }
        auto dfs = [&](auto self, int u, int p) -> std::pair<int, int> {
            int noDisc = price[u] * count[u];
            int disc = (price[u] / 2) * count[u];
            for (int v : adj[u]) {
                if (v != p) {
                    auto [cNo, cDisc] = self(self, v, u);
                    noDisc += std::min(cNo, cDisc);
                    disc += cNo;
                }
            }
            return {noDisc, disc};
        };
        auto [cNo, cDisc] = dfs(dfs, 0, -1);
        return std::min(cNo, cDisc);
    }
};

import java.util.*;

class Solution {
    public int minimumTotalPrice(int n, int[][] edges, int[] price, int[][] trips) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] count = new int[n];
        for (int[] t : trips) {
            List<Integer> path = new ArrayList<>();
            findPath(t[0], -1, t[1], adj, path);
            for (int u : path) count[u]++;
        }
        int[] res = dfs(0, -1, adj, price, count);
        return Math.min(res[0], res[1]);
    }

    private boolean findPath(int u, int p, int end, List<List<Integer>> adj, List<Integer> path) {
        path.add(u);
        if (u == end) return true;
        for (int v : adj.get(u)) {
            if (v != p && findPath(v, u, end, adj, path)) return true;
        }
        path.remove(path.size() - 1);
        return false;
    }

    private int[] dfs(int u, int p, List<List<Integer>> adj, int[] price, int[] count) {
        int noDisc = price[u] * count[u];
        int disc = (price[u] / 2) * count[u];
        for (int v : adj.get(u)) {
            if (v != p) {
                int[] c = dfs(v, u, adj, price, count);
                noDisc += Math.min(c[0], c[1]);
                disc += c[0];
            }
        }
        return new int[]{noDisc, disc};
    }
}

